/* Columnas que definen la ruta taxonómica, desde clase hasta especie. */
const TAXON_FIELDS = ["class","order","family","genus","species"];
/* Etiquetas legibles para mostrar el rango taxonómico en fichas y ayudas. */
const LEVEL_NAMES = {root:"Tots els registres",chondrichthyes:"Superclasse",osteichthyes:"Superclasse",actinopterygii:"Grup",class:"Classe / grup",order:"Ordre",family:"Família",genus:"Gènere",species:"Espècie"};
/* Colores de respaldo para los grupos principales. */
const COLORS = ["#174B73", "#9E303A", "#593B8C"];
// Gradiente jerárquico: cada nivel taxonómico se aclara y cambia de matiz
// progresivamente desde el color profundo del supergrupo hasta el tono de especie.
/* Color principal de cada gran linaje representado. */
const CLASS_BASES = {
 "Osteichthyes": "#103451",
 "Chondrichthyes": "#9E303A"
};
/* Escalas cromáticas: los tonos cambian al descender por la jerarquía. */
const CLASS_GRADIENTS = {
 "Osteichthyes": ["#103451", "#18577C", "#167A7C", "#29945E", "#B9E6A5"],
 "Chondrichthyes": ["#9E303A", "#D84E53", "#E97842", "#EAA84B", "#F4E7A1"]
};
/* Descripciones breves que se muestran al seleccionar un clado. */
/* Color neutro reutilizado en etiquetas y elementos SVG. */
const WHITE = "#ffffff";
/*
 * ESTADO DE LA VISUALIZACIÓN
 * root: árbol jerárquico completo; focus: nodo que se está explorando.
 * view: transformación actual del zoom; svg/g/labelLayer: capas del dibujo.
 * currentRows/currentFile: datos activos y nombre mostrado en la interfaz.
 * sizeMetric: variable elegida para dimensionar las burbujas.
 */
let root = null, focus = null, view = null, svg, g, labelLayer, pack,
    width = 900, height = 650, currentRows = [],
    currentFile = "peces_circle_packing(1).csv", sizeMetric = "observations";
// Memoria de imágenes de esta sesión: se conserva aunque la visualización se vuelva a dibujar.
const speciesPhotoCache = new Map();
/* Respeta la preferencia del sistema para reducir las animaciones. */
const reducedMotion = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
let motionEnabled = !reducedMotion, motionFrame = null, dragState = null, floatPhase = 0;
/* Formateador numérico localizado en catalán (separadores de miles, etc.). */
const fmt = new Intl.NumberFormat("ca-ES");
/*
 * DATOS Y VALIDACIÓN
 * El CSV se guarda dentro del propio HTML en Base64 para que el archivo pueda
 * abrirse sin tener que seleccionar un CSV externo. D3 interpreta las filas y
 * después se comprueba que existan las columnas necesarias y recuentos válidos.
 */
/* Decodifica el CSV incrustado y recupera el texto UTF-8 original. */
function decodeCSV(b64){const bytes=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));return new TextDecoder("utf-8").decode(bytes);}
/* Normaliza campos vacíos para que las rutas taxonómicas tengan valores explícitos. */
function normalize(v){const s=(v??"").toString().trim();return s || "Sin dato";}
/* Lee el CSV, valida columnas y recuentos, y devuelve filas listas para el análisis. */
function parseCSV(text){
 const parsed=d3.csvParse(text);
 const required=["class","order","family","genus","species","observaciones"];
 const missing=required.filter(k=>!parsed.columns.includes(k));
 if(missing.length) throw new Error("Falten columnes obligatòries: "+missing.join(", "));
 const rows=parsed.map((r,i)=>{const raw=(r.observaciones??"").trim().replace(",",".");const value=Number(raw);
  if(raw===""||!Number.isFinite(value)||value<0) throw new Error("El valor d’observacions de la fila "+(i+2)+" no és un nombre vàlid no negatiu.");
  const out={observaciones:value};TAXON_FIELDS.forEach(k=>out[k]=normalize(r[k]));return out;});
 if(!rows.length) throw new Error("El CSV no conté cap fila de dades.");
 return rows;
}
/*
 * CONSTRUCCIÓN DE LA JERARQUÍA
 * Convierte las filas del CSV en un árbol de taxones. Los grupos superiores
 * añadidos para la visualización son nodos organizativos; sus valores se calculan
 * a partir de los descendientes y no modifican los datos originales.
 */
/* Construye el árbol taxonómico y calcula los recuentos agregados de sus nodos. */
function buildHierarchy(rows){
 // La tabla original no se altera: esta ruta ampliada solo se utiliza para construir la jerarquía visual.
 // Los recuentos de cada nodo sintético se obtienen sumando los registros descendientes.
 const tree={name:"Tots els registres",level:"root",children:new Map(),value:0};
 rows.forEach(r=>{
  let n=tree;n.value+=r.observaciones;
  let path=[];
  if(r.class==="Elasmobranchii" || r.class==="Holocephali"){
   path=[{name:"Chondrichthyes",level:"chondrichthyes"},{name:r.class,level:"class"},...TAXON_FIELDS.slice(1).map(field=>({name:r[field],level:field}))];
  }else if(r.class==="Teleostei"){
   path=[{name:"Osteichthyes",level:"osteichthyes"},{name:"Actinopterygii",level:"actinopterygii"},{name:"Teleostei",level:"class"},...TAXON_FIELDS.slice(1).map(field=>({name:r[field],level:field}))];
  }else{
   path=TAXON_FIELDS.map(field=>({name:r[field],level:field}));
  }
  // Si no se conoce la especie, no crear una burbuja artificial «Sin dato».
  // Las observaciones se conservan y quedan agregadas en el último nivel conocido (género/familia).
  // Se omiten los marcadores de dato ausente en cualquier nivel taxonómico.
  // Así no aparecen círculos ficticios llamados «Sin dato»; las observaciones
  // continúan agregándose en los nodos conocidos de la ruta.
  path=path.filter(taxon=>String(taxon.name??"").trim().toLocaleLowerCase("es")!=="sin dato" &&
                          String(taxon.name??"").trim()!=="");
  path.forEach(({name,level})=>{
   if(!n.children.has(name))n.children.set(name,{name,level,children:new Map(),value:0,parent:n});
   n=n.children.get(name);n.value+=r.observaciones;
  });
 });
 function finish(n){if(n.children.size){n.children=Array.from(n.children.values()).map(finish);}else{delete n.children;}return n;}
 const hierarchy=d3.hierarchy(finish(tree)).sum(d=>d.children?0:(sizeMetric==="species"?1:d.value)).sort((a,b)=>b.value-a.value);
 hierarchy.eachAfter(n=>{
  n.obsValue=n.children?d3.sum(n.children,c=>c.obsValue):(Number(n.data.value)||0);
  n.speciesCount=n.children?d3.sum(n.children,c=>c.speciesCount):(n.data.level==="species" && String(n.data.name).trim().toLowerCase()!=="sin dato" ? 1 : 0);
 });
 return hierarchy;
}
/*
 * COLOR Y MÉTRICAS
 * Los colores siguen una escala propia para cada gran grupo. La variable elegida
 * por la persona usuaria determina si el área de los círculos representa especies
 * o registros de observación.
 */
/* Devuelve el color base asociado al linaje principal de un taxón. */
function classColor(name){
 return CLASS_BASES[name] || "#668A80";
}
/* Identifica la clase o linaje principal al que pertenece un nodo. */
function nodeClass(node){
 let n=node;
 while(n&&n.depth>1)n=n.parent;
 return n&&n.depth===1?n.data.name:"";
}
/* Selecciona el valor usado para el área de cada círculo según el selector activo. */
function metricValue(node){return sizeMetric==="species"?node.speciesCount:node.obsValue;}
/* Calcula el color de los nodos respetando el grupo y su nivel taxonómico. */
function orderColor(node){
 return color(node);
}
/* Centraliza la decisión cromática de cada nodo del circle packing. */
function color(node){
 if(node.depth===0) return "#f4f0e7";
 const cls=nodeClass(node);
 const stops=CLASS_GRADIENTS[cls]||CLASS_GRADIENTS.Osteichthyes;
 // Osteichthyes queda más oscuro que Actinopterygii y Teleostei.
 if(node.data.name==="Osteichthyes") return "#103451";
 if(node.data.name==="Chondrichthyes") return "#9E303A";
 let paletteIndex;
 if(cls==="Osteichthyes"){
   const level=node.data.level;
   if(level==="actinopterygii") paletteIndex=1;
   else if(level==="class") paletteIndex=2;
   else if(level==="order") paletteIndex=2;
   else if(level==="family") paletteIndex=3;
   else if(level==="genus") paletteIndex=3;
   else if(level==="species") paletteIndex=4;
   else paletteIndex=Math.min(stops.length-1,Math.max(1,node.depth-1));
 } else {
   const level=node.data.level;
   if(level==="class") paletteIndex=1;
   else if(level==="order") paletteIndex=2;
   else if(level==="family") paletteIndex=3;
   else if(level==="genus") paletteIndex=3;
   else if(level==="species") paletteIndex=4;
   else paletteIndex=Math.min(stops.length-1,Math.max(1,node.depth-1));
 }
 paletteIndex=Math.min(stops.length-1,paletteIndex);
 const base=d3.hsl(stops[paletteIndex]);
 if(node.depth===1) return base.formatHex();

 // Pequeñas variaciones entre hermanos mantienen legible la jerarquía
 // sin romper el degradado principal de cada supergrupo.
 const siblings=node.parent?.children||[];
 const i=Math.max(0,siblings.indexOf(node));
 const siblingShift=((i%5)-2)*0.018;
 const hueShift=((i%3)-1)*3.2;
 let light=Math.max(0.12,Math.min(0.92,base.l+siblingShift));
 let hue=(base.h+hueShift+360)%360;
 let sat=base.s;
 // En los niveles terminales, suavizamos ligeramente la saturación.
 if(node.depth>=4) sat=Math.max(0.78,sat*1.04);
 return d3.hsl(hue,sat,light).formatHex();
}
/*
 * PREPARACIÓN DEL LIENZO
 * Configura el SVG, define el recorte circular de las fotografías y coloca la
 * silueta decorativa del pez detrás de las burbujas taxonómicas.
 */
/* Prepara el lienzo SVG, las capas gráficas y la silueta decorativa del pez. */
function initSVG(){
 svg=d3.select("#viz");svg.selectAll("*").remove();
 const box=document.querySelector("#viz").getBoundingClientRect();width=Math.max(300,box.width);height=Math.max(380,box.height);
 svg.attr("viewBox",`0 0 ${width} ${height}`).attr("preserveAspectRatio","xMidYMid meet");
 // Definicions SVG necessàries per retallar cada fotografia exactament dins del cercle de l’espècie.
 svg.append("defs").attr("id","speciesImageDefs");
 // Silueta solicitada: se utiliza la imagen aportada por la usuaria.
 // El fondo blanco se ha convertido en transparencia y el pez se ha oscurecido
 // ligeramente para que se integre con el fondo beige sin tapar las burbujas.
 const fishImage = "data:image/png;base64,";
 svg.append("image")
   .attr("class","fish-silhouette")
   .attr("href",fishImage)
   .attr("x",-width*0.050)
   .attr("y",-height*0.035)
   .attr("width",width*1.10)
   .attr("height",height*1.03)
   .attr("preserveAspectRatio","xMidYMid meet")
   .attr("opacity",0.92)
   .style("pointer-events","none");
 g=svg.append("g");
 labelLayer=svg.append("g").attr("class","label-layer").style("pointer-events","none");
 pack=d3.pack().size([Math.max(250,width-24),Math.max(320,height-24)]).padding(3);
}
/* Activa un conjunto de filas, reconstruye el árbol y actualiza estadísticas y dibujo. */
function loadRows(rows,fileName){
 currentRows=rows;currentFile=fileName;nodeOffsets.clear();dragState=null;root=buildHierarchy(rows);
 pack=d3.pack().size([Math.max(250,width-24),Math.max(320,height-24)]).padding(3);
 root=pack(root);
 root.each(d=>{d.x=d.x+12;d.y=d.y+12;});
 focus=root;view=[root.x,root.y,root.r*2];
 document.querySelector("#sourceFile").textContent=fileName;
 document.querySelector("#statObs").textContent=fmt.format(d3.sum(rows,d=>d.observaciones));
 document.querySelector("#statSpecies").textContent=fmt.format(new Set(rows.map(d=>d.species).filter(name=>String(name).trim().toLowerCase()!=="sin dato")).size);
 document.querySelector("#statClasses").textContent=root.children.length;
 document.querySelector("#statOrders").textContent=new Set(rows.map(d=>d.order)).size;
 renderLegend();render();selectNode(root,false);preloadAllSpeciesPhotos();
 document.querySelector("#status").textContent=`${fmt.format(rows.length)} filas taxonómicas · ${fmt.format(d3.sum(rows,d=>d.observaciones))} observaciones sumadas.`;
}
/* Dibuja la leyenda de colores y actualiza sus referencias a la métrica seleccionada. */
function renderLegend(){
 const el=document.querySelector("#legend");el.innerHTML="";
 root.children.forEach(c=>{
  const base=classColor(c.data.name), item=document.createElement("div");item.className="legend-item";
  const dot=document.createElement("span");dot.className="dot";dot.style.background=base;
  const label=document.createElement("span");label.textContent=c.data.name;
  const scale=document.createElement("span");scale.className="scale-bar";scale.style.background=`linear-gradient(90deg, ${d3.interpolateRgb("#fffaf0",base)(.30)}, ${base}, ${d3.color(base).darker(1.45).formatHex()})`;
  const ends=document.createElement("div");ends.className="scale-ends";ends.innerHTML=`<span>Menos ${sizeMetric==="species"?"especies":"observaciones"}</span><span>Más</span>`;
  item.append(dot,label,scale,ends);el.append(item);
 });
}
/* Decide si una etiqueta cabe en el círculo y calcula un tamaño de texto adecuado. */
function fitLabel(d,scale){
 const r=d.r*scale;
 if(r<7)return null;
 const name=String(d.data.name||"").trim();
 if(!name)return null;
 // Etiquetas pequeñas y adaptativas. Los nombres largos se reducen dentro del ancho disponible.
 const maxWidth=Math.max(7,r*1.38);
 const maxHeight=Math.max(7,r*.54);
 const words=name.split(/\s+/);
 for(let font=Math.min(9.2,Math.max(3.8,r*.17));font>=3.3;font-=.2){
  let lines=[],line="";
  for(const word of words){
   if(!line){line=word;continue;}
   if((line+" "+word).length*font*.53<=maxWidth){line+=" "+word;}
   else {lines.push(line);line=word;}
  }
  if(line)lines.push(line);
  // Evitar fragmentar taxones de una sola palabra; SVG textLength los encoge sin partirlos.
  if(words.length===1)lines=[name];
  if(lines.length>2)continue;
  const rawWidth=Math.max(...lines.map(l=>l.length),1)*font*.53;
  const textWidth=Math.min(maxWidth,rawWidth);
  const textHeight=lines.length*font*.94;
  if(textHeight<=maxHeight)return {lines,font,width:textWidth,height:textHeight,rawWidth};
 }
 // Último recurso para que las etiquetas prioritarias no desaparezcan.
 if(r>=11)return {lines:[name],font:Math.max(3.1,Math.min(4.2,r*.12)),width:maxWidth,height:4.2,rawWidth:name.length*4.2*.53};
 return null;
}
/* Calcula una posición viable para las etiquetas curvas dentro de la geometría disponible. */
function labelSlot(node,k,label,geomMap){
 const geom=geomMap.get(node); if(!geom)return null;
 const r=geom.r*k, h=label.height;
 if(r<8) return null;
 // La geometría reserva una franja superior dentro del grupo; aquí se evita además cualquier colisión residual.
 const candidates=[];
 const ys=[-.76,-.70,-.64,-.58,-.52,-.46,-.38,-.28,.28,.40,.52,.62];
 const xs=[0,-.08,.08,-.16,.16];
 for(const yn of ys){for(const xn of xs)candidates.push([xn*r,yn*r]);}
 let best=null,bestScore=Infinity;
 for(const [x,y] of candidates){
   const halfH=h/2+1;
   const edge=Math.abs(y)+halfH;
   if(edge>=r*.94) continue;
   const chord=2*Math.sqrt(Math.max(0,(r*.94)*(r*.94)-edge*edge));
   const w=Math.min(label.width,chord);
   if(w<Math.min(10,label.rawWidth*.30)) continue;
   const corners=[[x-w/2,y-h/2],[x+w/2,y-h/2],[x-w/2,y+h/2],[x+w/2,y+h/2]];
   if(corners.some(([a,b])=>Math.hypot(a,b)>r*.94)) continue;
   let overlap=0;
   for(const child of (node.children||[])){
     const cg=geomMap.get(child); if(!cg)continue;
     const cx=(cg.x-geom.x)*k, cy=(cg.y-geom.y)*k, cr=cg.r*k;
     const nx=Math.max(x-w/2,Math.min(x+w/2,cx));
     const ny=Math.max(y-h/2,Math.min(y+h/2,cy));
     const dist=Math.hypot(cx-nx,cy-ny);
     if(dist<cr+1) overlap += (cr+1-dist)*(cr+1-dist);
   }
   const score=overlap*10000 + Math.abs(x)*.2 + Math.abs(y/r+.70)*2;
   if(overlap<.01 && score<bestScore){bestScore=score;best={x,y,width:w};}
 }
 return best;
}
/*
 * DIBUJO Y ETIQUETAS
 * Dibuja los nodos en el SVG y decide qué nombres caben en cada círculo.
 * Las etiquetas se mantienen en una capa independiente para que queden por
 * encima de las burbujas y puedan seguir sus arcos cuando corresponde.
 */
/* Dibuja o actualiza círculos, fotografías y etiquetas para el estado actual del árbol. */
function render(){
 if(!root)return;
 initSVG();
 const nodes=root.descendants().filter(d=>d.depth>0);
 const selection=g.selectAll("g.node").data(nodes,d=>d.ancestors().map(a=>a.data.name).reverse().join(" / "));
 const enter=selection.enter().append("g").attr("class","node").attr("tabindex",0).attr("role","button")
   .attr("aria-label",d=>`${d.data.name}, ${fmt.format(sizeMetric==="species"?d.speciesCount:d.obsValue)} ${sizeMetric==="species"?"especies":"observaciones"}`)
   .on("click",(event,d)=>{event.stopPropagation();selectNode(d,true);if(d.data.level==="species")showSpeciesPhoto(d.data.name);else closeSpeciesPhoto();})
   .on("keydown",(event,d)=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();selectNode(d,true);if(d.data.level==="species")showSpeciesPhoto(d.data.name);else closeSpeciesPhoto();}if(event.key==="Escape"){selectNode(d.parent||root,true);}})
   .on("mousemove",(event,d)=>showTooltip(event,d)).on("mouseleave",hideTooltip);
 // Dragging changes only the visual offset of the selected node; descendants travel with it.
 enter.call(d3.drag()
   .on("start",function(event,d){
     d3.select(this).classed("dragging",true);
     dragState={node:d,startX:event.x,startY:event.y,baseX:d.x,baseY:d.y,dx:0,dy:0};
     hideTooltip();
   })
   .on("drag",function(event,d){
     if(!dragState||dragState.node!==d)return;
     dragState.dx=event.x-dragState.startX;
     dragState.dy=event.y-dragState.startY;
     applyNodeOffsets();
   })
   .on("end",function(){
     d3.select(this).classed("dragging",false);
     // Keep a modest offset after release; animation will gently settle it back.
     if(dragState)dragState.releaseAt=performance.now();
   }));
 enter.append("circle");
 // Cada especie dispone de una imagen SVG recortada por el mismo círculo.
 enter.each(function(d){
   const key=d.ancestors().map(a=>a.data.name).reverse().join(" / ");
   const id="species-clip-"+Math.abs(hashLabel(key));
   d._photoClipId=id;
   const defs=svg.select("#speciesImageDefs");
   const cp=defs.append("clipPath").attr("id",id).attr("clipPathUnits","userSpaceOnUse");
   cp.append("circle").attr("r",0);
   d3.select(this).append("image").attr("class","species-node-photo")
     .attr("x",0).attr("y",0).attr("width",0).attr("height",0)
     .attr("preserveAspectRatio","xMidYMid slice")
     .attr("clip-path",`url(#${id})`).style("display","none")
     .style("cursor","pointer").style("pointer-events","all")
     .on("click",function(event,node){
       event.stopPropagation();
       const info=speciesPhotoCache.get(node.data.name);
       if(info && info.source) window.open(info.source,"_blank","noopener,noreferrer");
     });
 });
 // Las etiquetas viven en una capa SVG independiente, dibujada por encima de todas las burbujas.
 const labels=labelLayer.selectAll("g.label-node").data(nodes,d=>d.ancestors().map(a=>a.data.name).reverse().join(" / "));
 const labelEnter=labels.enter().append("g").attr("class","label-node");
 labelEnter.append("path").attr("class","label-arc").attr("fill","none").attr("stroke","none");
 labelEnter.append("text").attr("class","label").append("textPath").attr("class","label-text-path");
 labels.exit().remove();
 enter.merge(selection).classed("selected",d=>focus&&d===focus)
   .select("circle").attr("r",d=>d.r).attr("fill",d=>color(d))
   .attr("fill-opacity",1)
   .attr("stroke","none")
   .attr("stroke-width",0);
 // Al redibujar (al entrar en un grupo, volver atrás o cambiar de tamaño),
 // recupera las fotografías ya consultadas desde la memoria y no vuelve a buscarlas.
 g.selectAll("g.node").each(function(node){
   if(node.data.level !== "species") return;
   const cached = speciesPhotoCache.get(node.data.name);
   const photo = d3.select(this).select("image.species-node-photo");
   if(cached?.image) photo.attr("href",cached.image).style("display",null);
   else photo.style("display","none");
 });
 selection.exit().remove();
 svg.on("click",()=>selectNode(focus?.parent||root,true));
 zoomTo(focus||root,false);
 document.querySelector("#backBtn").disabled=!focus||focus===root;
 updateBreadcrumb();
 startMotion();
}
/* Determina qué etiquetas deben mostrarse en el nivel de zoom activo. */
function labelVisible(n, active){ return active===root ? n.depth===1 : n.parent===active; }
/* Separa etiquetas cercanas para reducir solapamientos en la vista actual. */
function calculateLabelRepulsion(active, k){
 const offsets=new Map();
 if(!root)return offsets;
 // Keep a clear strip around each visible title by nudging the bubbles directly inside that group.
 root.descendants().forEach(parent=>{
   if(!labelVisible(parent,active))return;
   const rr=parent.r*k;
   const name=parent.data.name||"";
   const font=Math.max(8,Math.min(14,rr*0.24));
   const labelWidth=Math.min(rr*1.55,Math.max(font*2,name.length*font*0.54));
   const labelHeight=font*1.55;
   const labelY=-rr*0.57;
   const halfW=labelWidth/2, halfH=labelHeight/2;
   (parent.children||[]).forEach(child=>{
     const cx=(child.x-parent.x)*k, cy=(child.y-parent.y)*k, cr=child.r*k;
     const nearestX=Math.max(-halfW,Math.min(halfW,cx));
     const nearestY=Math.max(labelY-halfH,Math.min(labelY+halfH,cy));
     const dx=cx-nearestX, dy=cy-nearestY;
     if(dx*dx+dy*dy < (cr+5)*(cr+5)){
       // Prefer moving downward; it preserves the group hierarchy and keeps the title unobstructed.
       const push=Math.max(0,(labelY+halfH+cr+7)-cy);
       offsets.set(child,{x:0,y:push});
     }
   });
 });
 return offsets;
}
/* Propaga los ajustes de posición de etiquetas a los nodos descendientes. */
function inheritedRepulsion(n, offsets){
 let x=0,y=0;
 for(let a=n;a&&a.depth>0;a=a.parent){const o=offsets.get(a);if(o){x+=o.x;y+=o.y;}}
 return {x,y};
}
/* Anima la transición hacia el nodo elegido y recalcula la escala visible. */
function zoomTo(d,animate,zoomFactor=1){
 if(!d||!g)return;
 focus=d;
 const target=[d.x,d.y,Math.max(2,(d.r*2+12)/zoomFactor)];
 const start=view||target;
 const apply=v=>{
   view=v;
   const k=height/v[2];
   let labelCandidates=[];
   if(d===root){
     const teleostei=root.descendants().find(n=>n.data.name==="Teleostei");
     const elasmobranchii=root.descendants().find(n=>n.data.name==="Elasmobranchii");
     const teleostSubgroups=teleostei?(teleostei.children||[]).slice().sort((a,b)=>b.value-a.value).slice(0,12):[];
     const elasmobranchSubgroups=elasmobranchii?(elasmobranchii.children||[]).slice().sort((a,b)=>b.value-a.value).slice(0,3):[];
     const osteichthyes=root.children.find(n=>n.data.name==="Osteichthyes");
     const chondrichthyes=root.children.find(n=>n.data.name==="Chondrichthyes");
     // En la vista general priorizamos los dos supergrupos y los dos clados principales solicitados.
     labelCandidates=[...root.children,teleostei,elasmobranchii,...teleostSubgroups,...elasmobranchSubgroups].filter(Boolean);
   } else {
     // En els grups de peixos cartilaginosos mostrem més subdivisions:
     // en cas contrari, els ordres petits desapareixen del mapa en fer zoom.
     const maxLabels = d.data.name === "Teleostei" ? 18 :
       ["Chondrichthyes","Elasmobranchii","Holocephali"].includes(d.data.name) ? 30 : 12;
     labelCandidates=(d.children||[]).slice().sort((a,b)=>b.value-a.value).slice(0,maxLabels);
     if(!labelCandidates.length&&d!==root)labelCandidates=[d];
   }
   const rankedLabels=new Set(labelCandidates);
   // Contraer ligeramente los hijos de cada círculo etiquetado y desplazarlos hacia abajo.
   // Así queda una banda limpia para el nombre sin sacar descendientes del círculo padre.
   const geomMap=new Map();
   function mapGeometry(n){
     let geom;
     if(!n.parent){geom={x:n.x,y:n.y,r:n.r};}
     else{
       const pg=geomMap.get(n.parent);
       const scale=pg.r/Math.max(1,n.parent.r)*(rankedLabels.has(n.parent) ? 0.91 : 1);
       const shift=rankedLabels.has(n.parent)?pg.r*.055:0;
       geom={x:pg.x+(n.x-n.parent.x)*scale,y:pg.y+(n.y-n.parent.y)*scale+shift,r:n.r*scale};
     }
     geomMap.set(n,geom);
     (n.children||[]).forEach(mapGeometry);
   }
   mapGeometry(root);
   activeDisplayGeometry=geomMap;
   g.selectAll("g.node")
     .attr("transform",n=>{const q=geomMap.get(n);return `translate(${width/2+(q.x-v[0])*k},${height/2+(q.y-v[1])*k})`;});
   g.selectAll("g.node circle").attr("r",n=>geomMap.get(n).r*k);
   g.selectAll("g.node").each(function(n){
     const r=geomMap.get(n).r*k;
     const group=d3.select(this);
     group.select("image.species-node-photo").attr("x",-r).attr("y",-r).attr("width",2*r).attr("height",2*r);
     svg.select("#"+n._photoClipId+" circle").attr("r",r);
   });
   labelLayer.selectAll("g.label-node").attr("transform",n=>{const q=geomMap.get(n);return `translate(${width/2+(q.x-v[0])*k},${height/2+(q.y-v[1])*k})`;});
   labelLayer.selectAll("g.label-node").classed("species-label",n=>n.data.level==="species").each(function(n){
     const group=d3.select(this), text=group.select("text"), textPath=text.select("textPath");
     const screenR=geomMap.get(n).r*k;
     const keyOverviewLabel=d===root && ["Osteichthyes","Chondrichthyes","Teleostei","Elasmobranchii"].includes(n.data.name);
     const cartilaginousFocus=["Chondrichthyes","Elasmobranchii","Holocephali"].includes(d.data.name);
     const shouldLabel=rankedLabels.has(n)&&screenR>=(keyOverviewLabel ? 6.5 : (cartilaginousFocus ? 6.2 : d.data.name === "Teleostei" ? 7 : 8));
     const name=String(n.data.name||"");
     if(!shouldLabel){text.style("display","none");return;}
     // Etiqueta siguiendo el arco superior interior de su propio círculo.
     // La curva queda justo debajo del perímetro y dentro de la burbuja.
     const radius=screenR;
     // Arco superior interior. La etiqueta de la clase dominante (Teleostei)
     // sube ligeramente para quedar más próxima al perímetro superior.
     const isTeleostei = n.data.name === "Teleostei" && d === root;
     const isOsteichthyes = n.data.name === "Osteichthyes" && d === root;
     const isElasmobranchii = n.data.name === "Elasmobranchii" && d === root;
     const isTopLabel = isTeleostei || isOsteichthyes || isElasmobranchii;
     // Solo los tres nombres principales usan un arco interior específico para que no floten fuera.
     const half=Math.max(3,radius*(isOsteichthyes ? .68 : isTeleostei ? .72 : isElasmobranchii ? .68 : .72));
     // Arco superior interior. Para Elasmobranchii se usa un arco circular
     // auténtico, con la misma curvatura que el perímetro de su burbuja.
     const arcId="label-arc-"+Math.abs(hashLabel(n.ancestors().map(a=>a.data.name).reverse().join("/")));
     const labelPath = group.select("path.label-arc").attr("id",arcId);
     if(isElasmobranchii){
       const arcR=radius*.90;
       // Bajar un poco el arco completo manteniendo exactamente la curvatura circular.
       const arcCenterY=radius*.055;
       const endY=arcCenterY-Math.sqrt(Math.max(0,arcR*arcR-half*half));
       labelPath.attr("d",`M ${-half},${endY} A ${arcR},${arcR} 0 0 1 ${half},${endY}`);
     } else {
       const endY = isOsteichthyes ? -radius*.79 : isTeleostei ? -radius*.76 : -radius*.40;
       const controlY = isOsteichthyes ? -radius*1.02 : isTeleostei ? -radius*1.01 : -radius*1.16;
       labelPath.attr("d",`M ${-half},${endY} Q 0,${controlY} ${half},${endY}`);
     }
     const available=half*2.0;
     const font=Math.max(4.2,Math.min(13,radius*.18,available/(Math.max(1,name.length)*.49)));
     text.attr("font-family",'Inter, "Aptos", "Segoe UI", sans-serif')
       .attr("font-size",font).attr("font-weight",600).attr("fill",n.data.level==="species"?"#17211d":"#ffffff")
       .attr("text-anchor","middle").attr("stroke","none").attr("paint-order","normal")
       .style("display",null);
     textPath.attr("href","#"+arcId).attr("startOffset","50%").attr("text-anchor","middle").attr("fill",n.data.level==="species"?"#17211d":"#ffffff")
       .attr("textLength",Math.max(3,Math.min(available,name.length*font*.56)))
       .attr("lengthAdjust","spacingAndGlyphs").text(name);
   });
   applyNodeOffsets();
 };;
 if(animate&&!reducedMotion){
   const interp=d3.interpolateZoom(start,target);
   d3.transition().duration(650).tween("zoom",()=>t=>apply(interp(t)));
 }else apply(target);
}
/* Genera un valor determinista a partir del texto para repartir posiciones de forma estable. */
function hashLabel(value){let h=2166136261;for(let i=0;i<value.length;i++){h^=value.charCodeAt(i);h=Math.imul(h,16777619);}return h|0;}
/* Añade los elementos de texto SVG que forman una etiqueta multilínea. */
function linesAppend(text,label,x){
 label.lines.forEach((line,i)=>text.append("tspan").attr("x",x).attr("dy",i===0?0:label.font*.98).text(line));
}
const nodeOffsets = new Map();
let labelOffsets = new Map();
let activeDisplayGeometry = new Map();
// Factor de zoom manual: cada pulsación de + acerca un poco más y − retrocede.
let manualZoomFactor = 1;
/* Aplica los desplazamientos manuales de los nodos tras una interacción o animación. */
function applyNodeOffsets(){
 if(!root||!g||!view)return;
 const k=height/view[2];
 function transform(n){
   let ox=0,oy=0;
   for(let a=n;a&&a.depth>0;a=a.parent){
     const drag=nodeOffsets.get(a);if(drag){ox+=drag.x*k;oy+=drag.y*k;}
   }
   // A la vista general, mou una mica cap a la dreta el clade vermell i tots els seus descendents.
   const inChondrichthyes = n.ancestors().some(a=>a.data && a.data.name==="Chondrichthyes");
   // Desplaçament lleu cap a l’esquerra per equilibrar el clade vermell en la vista general.
   const overviewShift = (focus===root && inChondrichthyes) ? width*0.04 : 0;
   const q=activeDisplayGeometry.get(n)||n;
   return `translate(${width/2+(q.x-view[0])*k+ox+overviewShift},${height/2+(q.y-view[1])*k+oy})`;
 }
 g.selectAll("g.node").attr("transform",transform);
 labelLayer.selectAll("g.label-node").attr("transform",transform);
}

/* Gestiona el movimiento sutil y continuo de las burbujas cuando está activado. */
function startMotion(){
 if(motionFrame!==null){cancelAnimationFrame(motionFrame);motionFrame=null;}
 if(!motionEnabled||reducedMotion)return;
 let last=0;
 const tick=now=>{
   if(!motionEnabled){motionFrame=null;return;}
   if(now-last>55){
     last=now;floatPhase+=0.018;
     // Very subtle sibling-group drift, anchored to the hierarchy. Parent/child relationships are never recalculated.
     root.descendants().forEach((n,i)=>{
       if(n.depth===0)return;
       const parent=n.parent;
       const phase=(i%17)*0.71 + n.depth*0.8;
       const targetX=Math.sin(floatPhase+phase)*1.25;
       const targetY=Math.cos(floatPhase*0.83+phase)*1.25;
       const old=nodeOffsets.get(n)||{x:0,y:0,until:0};
       if(!(dragState&&dragState.node===n)){
         const decay=old.until&&old.until!==Infinity?Math.max(0,Math.min(1,(now-old.until)/700)):1;
         const blend=0.025;
         nodeOffsets.set(n,{x:old.x*(1-blend)+targetX*blend*decay,y:old.y*(1-blend)+targetY*blend*decay,until:0});
       }
     });
     applyNodeOffsets();
   }
   motionFrame=requestAnimationFrame(tick);
 };
 motionFrame=requestAnimationFrame(tick);
}
document.querySelector("#motionToggle")?.addEventListener("click",()=>{
 motionEnabled=!motionEnabled;
 const b=document.querySelector("#motionToggle");
 b.textContent=motionEnabled?"Atura el moviment":"Reprèn el moviment";
 b.setAttribute("aria-pressed",String(motionEnabled));
 if(motionEnabled)startMotion();else if(motionFrame!==null){cancelAnimationFrame(motionFrame);motionFrame=null;}
});
let tooltip;
/* Construye y coloca la ficha emergente con la taxonomía y los recuentos del nodo. */
function showTooltip(event,d){
 if(!tooltip){
  tooltip=document.createElement("div");
  Object.assign(tooltip.style,{position:"fixed",zIndex:10,pointerEvents:"none",background:"#fffdf8",border:"1px solid #d8cfbf",borderRadius:"8px",padding:"10px 12px",color:"#28332f",fontSize:"12px",lineHeight:"1.55",boxShadow:"0 5px 18px #28332f18",maxWidth:"260px",minWidth:"190px"});
  document.body.appendChild(tooltip);
 }
 const lineage=d.ancestors().reverse().filter(n=>n.depth>0);
 const taxonomy=[{rank:"Regne",name:"Animalia"},{rank:"Fílum",name:"Chordata"}];
 lineage.forEach(n=>{
  const level=n.data.level, name=n.data.name;
  let rank="Clade";
  if(level==="osteichthyes") rank="Superclasse";
  else if(level==="actinopterygii") rank="Classe";
  else if(level==="class" && name==="Teleostei") rank="Infraclasse";
  else if(level==="chondrichthyes") rank="Clade";
  else if(level==="class") rank="Grup";
  else if(level==="order") rank="Ordre";
  else if(level==="family") rank="Família";
  else if(level==="genus") rank="Gènere";
  else if(level==="species") rank="Espècie";
  taxonomy.push({rank,name});
 });
 const taxRows=taxonomy.map(t=>`<div style="display:grid;grid-template-columns:78px minmax(0,1fr);gap:7px;padding:2px 0;border-bottom:1px solid #eee9df"><span style="color:#69746e">${escapeHTML(t.rank)}</span><b style="font-weight:650;overflow-wrap:anywhere">${escapeHTML(t.name)}</b></div>`).join("");
 tooltip.innerHTML=`<div style="font-weight:750;font-size:13px;margin-bottom:3px">${escapeHTML(d.data.name)}</div><div style="color:#69746e;font-size:10px;text-transform:uppercase;letter-spacing:.08em;margin-bottom:7px">${LEVEL_NAMES[d.data.level]||"Vista general"}</div><div style="font-size:11px;font-weight:750;margin-bottom:3px">Taxonomia</div><div style="margin-bottom:7px">${taxRows}</div><div style="display:flex;justify-content:space-between;gap:16px"><span>Espècies totals</span><b>${fmt.format(d.speciesCount)}</b></div><div style="display:flex;justify-content:space-between;gap:16px"><span>Observacions totals</span><b>${fmt.format(d.obsValue)}</b></div>`;
 tooltip.style.maxWidth="300px";tooltip.style.minWidth="220px";
 tooltip.style.display="block";
 const tw=tooltip.offsetWidth||300, th=tooltip.offsetHeight||180;
 tooltip.style.left=Math.max(8,Math.min(event.clientX+14,innerWidth-tw-8))+"px";
 tooltip.style.top=Math.max(8,Math.min(event.clientY+14,innerHeight-th-8))+"px";
}
/* Oculta la ficha emergente cuando deja de ser necesaria. */
function hideTooltip(){if(tooltip)tooltip.style.display="none";}
/* Escapa caracteres HTML para mostrar texto procedente de datos de forma segura. */
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}

/* FOTOGRAFÍAS: consultas, caché y estado de las ventanas */
let speciesPhotoRequest = 0;
let photoCompareRequest = 0;

// Obté una fotografia reutilitzant la memòria cau de la fitxa individual.
// Es limita el nombre de consultes simultànies per no carregar massa les APIs.
/* Busca una fotografía en Wikipedia y, si no aparece, intenta localizarla en Commons. */
async function fetchSpeciesPhotoData(scientificName){
 if(speciesPhotoCache.has(scientificName)) return speciesPhotoCache.get(scientificName);
 let result=null;
 try{
  const api="https://en.wikipedia.org/w/api.php?origin=*&action=query&format=json&redirects=1&prop=pageimages%7Cinfo&piprop=thumbnail&pithumbsize=500&inprop=url&titles="+encodeURIComponent(scientificName);
  const r=await fetch(api);
  if(r.ok){const data=await r.json();const page=Object.values(data.query?.pages||{}).find(x=>!x.missing);
   if(page?.thumbnail?.source)result={image:page.thumbnail.source,source:page.fullurl||("https://en.wikipedia.org/wiki/"+encodeURIComponent((page.title||scientificName).replace(/ /g,"_"))),label:"Wikipedia"};}
 }catch(e){}
 if(!result){
  try{
   const url="https://commons.wikimedia.org/w/api.php?origin=*&action=query&format=json&generator=search&gsrnamespace=6&gsrlimit=8&gsrsearch="+encodeURIComponent('"'+scientificName+'"')+"&prop=imageinfo&iiprop=url%7Cextmetadata&iiurlwidth=500";
   const r=await fetch(url);if(r.ok){const data=await r.json();const pages=Object.values(data.query?.pages||{});
    const norm=t=>String(t||"").toLowerCase().replace(/[_-]+/g," ").replace(/\s+/g," ").trim();const needle=norm(scientificName);
    const hit=pages.map(page=>({page,info:page.imageinfo?.[0],title:norm(page.title)})).filter(x=>x.info?.thumburl||x.info?.url).find(x=>x.title.includes(needle));
    if(hit)result={image:hit.info.thumburl||hit.info.url,source:hit.info.descriptionurl||("https://commons.wikimedia.org/wiki/"+encodeURIComponent(hit.page.title.replace(/ /g,"_"))),label:"Wikimedia Commons"};
   }
  }catch(e){}
 }
 speciesPhotoCache.set(scientificName,result);return result;
}

// Carga progresivamente las fotografías de todas las especies para que también
// aparezcan en la vista general. Se limita la concurrencia para no lanzar cientos
// de peticiones a la vez; las imágenes encontradas se guardan en la caché.
let photoPreloadRunning = false;
let photoPreloadPromise = null;
/* Consulta progresivamente las especies en segundo plano con concurrencia limitada. */
async function preloadAllSpeciesPhotos(){
 if(!root) return;
 // Si la cola ya está activa, se deja continuar: navegar por la visualización
 // no debe cancelar ni reiniciar las consultas pendientes.
 if(photoPreloadRunning) return photoPreloadPromise;
 photoPreloadRunning = true;
 photoPreloadPromise = (async()=>{
  // Prioritza les espècies amb més observacions, que normalment són les que
  // tenen els cercles més grans quan la visualització representa observacions.
  // Així, les primeres peticions a Wikipedia/Commons corresponen als tàxons
  // més destacats i les seves fotografies poden aparèixer abans.
  const species = root.descendants()
   .filter(n => n.data.level === "species" && n.data.name)
   .sort((a, b) => (b.obsValue || 0) - (a.obsValue || 0));

  // Conserva l'ordre de prioritat i elimina noms científics repetits.
  const names = [...new Set(species.map(n => n.data.name))];
  let next = 0, completed = 0, found = 0;
  const status = document.getElementById("status");
  const worker = async()=>{
   while(next < names.length){
    const scientificName = names[next++];
    let data = null;
    try { data = await fetchSpeciesPhotoData(scientificName); } catch(e) { data = null; }
    if(data?.image){
     found++;
     // La caché es la fuente principal. Si esta especie está visible ahora,
     // aplicamos la imagen directamente; si no, render() la recuperará al volver.
     g.selectAll("g.node").filter(n=>n.data.level === "species" && n.data.name === scientificName)
      .select("image.species-node-photo").attr("href",data.image).style("display",null);
    }
    completed++;
    if(completed % 10 === 0 || completed === names.length){
     status.textContent = `Fotografies de les espècies: ${completed}/${names.length} consultades · ${found} disponibles.`;
    }
   }
  };
  // Un nombre moderat de treballadors evita saturar Wikipedia/Commons, però
  // manté la cua avançant mentre l'usuari navega per la visualització.
  await Promise.all(Array.from({length:Math.min(5,names.length)},worker));
  status.textContent = `Fotografies consultades: ${completed}/${names.length} · ${found} disponibles. Les imatges que falten no s'han trobat a les fonts consultades.`;
 })().catch(()=>{
  document.getElementById("status").textContent = "La visualització funciona, però algunes fotografies no s'han pogut consultar.";
 }).finally(()=>{photoPreloadRunning=false;photoPreloadPromise=null;});
 return photoPreloadPromise;
}
/* Abre una galería comparativa con las fotografías de las especies del grupo activo. */
async function openPhotoComparison(node){
 if(!node||!node.children)return;
 const modal=document.getElementById("photoCompareModal"),grid=document.getElementById("photoCompareGrid"),status=document.getElementById("photoCompareStatus");
 const species=node.descendants().filter(n=>n.data.level==="species").sort((a,b)=>a.data.name.localeCompare(b.data.name));
 const request=++photoCompareRequest;
 document.getElementById("photoCompareTitle").textContent="Comparar espècies · "+node.data.name;
 document.getElementById("photoCompareSubtitle").textContent=species.length+" espècies · selecciona una fotografia per obrir-ne la font.";
 grid.replaceChildren();status.textContent="Carregant fotografies…";modal.hidden=false;
 if(!species.length){status.textContent="Aquest grup no conté espècies identificades.";return;}
 const cards=species.map(n=>{const card=document.createElement("article");card.className="compare-species-card";
  const link=document.createElement("a");link.className="compare-photo";link.href="#";link.target="_blank";link.rel="noopener noreferrer";link.textContent="Cercant imatge…";
  const name=document.createElement("div");name.className="compare-name";name.textContent=n.data.name;
  const source=document.createElement("a");source.className="compare-source";source.hidden=true;source.target="_blank";source.rel="noopener noreferrer";source.textContent="Obrir font ↗";
  link.addEventListener("click",e=>{if(!link.dataset.source)e.preventDefault();});
  card.append(link,name,source);grid.append(card);return {name:n.data.name,link,source};});
 let next=0,done=0;const worker=async()=>{while(next<cards.length&&request===photoCompareRequest){const item=cards[next++];const data=await fetchSpeciesPhotoData(item.name);
  if(request!==photoCompareRequest)return;
  if(data?.image){item.link.href=data.source;item.link.dataset.source="yes";item.link.textContent="";const image=document.createElement("img");image.loading="lazy";image.alt=item.name;image.src=data.image;item.link.append(image);item.source.href=data.source;item.source.hidden=false;}
  else{item.link.removeAttribute("href");item.link.textContent="Fotografia no disponible";}
  done++;status.textContent=`Fotografies consultades: ${done} de ${cards.length}.`;}}
 await Promise.all(Array.from({length:Math.min(4,cards.length)},worker));
 if(request===photoCompareRequest)status.textContent=`Galeria completa: ${cards.filter(c=>c.source.href).length} fotografies disponibles de ${cards.length} espècies.`;
}
/* Eventos de la galería comparativa: abrir, cerrar y cancelar solicitudes obsoletas. */
document.getElementById("comparePhotosBtn").addEventListener("click",()=>openPhotoComparison(focus));
document.getElementById("photoCompareClose").addEventListener("click",()=>{photoCompareRequest++;document.getElementById("photoCompareModal").hidden=true;});
document.getElementById("photoCompareModal").addEventListener("click",e=>{if(e.target.id==="photoCompareModal"){photoCompareRequest++;e.currentTarget.hidden=true;}});
document.addEventListener("keydown",e=>{if(e.key==="Escape")document.getElementById("photoCompareModal").hidden=true;});
/* Cierra la tarjeta flotante de fotografía de una especie. */
function closeSpeciesPhoto(){
 const card=document.getElementById("speciesPhotoCard");
 if(card)card.hidden=true;
}
/* Abre la ficha de una especie y solicita su imagen si aún no está en caché. */
async function showSpeciesPhoto(scientificName){
 const card=document.getElementById("speciesPhotoCard");
 const title=document.getElementById("speciesPhotoTitle");
 const img=document.getElementById("speciesPhotoImg");
 const placeholder=document.getElementById("speciesPhotoPlaceholder");
 const status=document.getElementById("speciesPhotoStatus");
 const source=document.getElementById("speciesPhotoSource");
 const requestId=++speciesPhotoRequest;
 card.hidden=true; title.textContent=scientificName;
 img.hidden=true; img.removeAttribute("src"); img.alt="Fotografia de "+scientificName;
 placeholder.hidden=false; placeholder.textContent="Cercant una imatge…";
 status.textContent="Cercant a Wikipedia i Wikimedia Commons…";
 source.hidden=true; source.removeAttribute("href");
 if(speciesPhotoCache.has(scientificName)){
   applySpeciesPhoto(speciesPhotoCache.get(scientificName),requestId,scientificName); return;
 }
 let result=null;
 // Use Wikipedia's Action API (CORS-enabled with origin=*); the REST summary
 // endpoint can fail in embedded previews or return 404 for valid taxa.
 const api="https://en.wikipedia.org/w/api.php?origin=*&action=query&format=json&redirects=1&prop=pageimages%7Cinfo&piprop=thumbnail&pithumbsize=720&inprop=url&titles="+encodeURIComponent(scientificName);
 try{
   const r=await fetch(api);
   if(r.ok){
     const data=await r.json();
     const page=Object.values(data.query?.pages||{}).find(x=>!x.missing);
     if(page?.thumbnail?.source) result={image:page.thumbnail.source,source:page.fullurl||("https://en.wikipedia.org/wiki/"+encodeURIComponent((page.title||scientificName).replace(/ /g,"_"))),label:"Wikipedia"};
   }
 }catch(e){ /* Continue to Commons if Wikipedia is unavailable. */ }
 // Commons search: try the exact binomial first, then a looser query.
 if(!result){
   const queries=['"'+scientificName+'"',scientificName];
   for(const q of queries){
     try{
       const url="https://commons.wikimedia.org/w/api.php?origin=*&action=query&format=json&generator=search&gsrnamespace=6&gsrlimit=10&gsrsearch="+encodeURIComponent(q)+"&prop=imageinfo&iiprop=url%7Cextmetadata&iiurlwidth=720";
       const r=await fetch(url);
       if(!r.ok) continue;
       const data=await r.json();
       const pages=Object.values(data.query?.pages||{});
       // Prefer filenames containing the scientific name; avoid arbitrary unrelated results.
       const norm=t=>String(t||"").toLowerCase().replace(/[_-]+/g," ").replace(/\s+/g," ").trim();
       const needle=norm(scientificName);
       const ranked=pages.map(page=>({page,info:page.imageinfo?.[0],title:norm(page.title)}))
         .filter(x=>x.info?.thumburl||x.info?.url)
         .sort((a,b)=>Number(b.title.includes(needle))-Number(a.title.includes(needle)));
       const hit=ranked.find(x=>x.title.includes(needle)) || (q===scientificName?ranked[0]:null);
       if(hit){const info=hit.info;result={image:info.thumburl||info.url,source:info.descriptionurl||("https://commons.wikimedia.org/wiki/"+encodeURIComponent(hit.page.title.replace(/ /g,"_"))),label:"Wikimedia Commons"};break;}
     }catch(e){ /* Try the next query/provider. */ }
   }
 }
 if(requestId!==speciesPhotoRequest)return;
 speciesPhotoCache.set(scientificName,result);
 applySpeciesPhoto(result,requestId,scientificName);
}
/* Actualiza la ficha con el resultado de imagen y controla las respuestas antiguas. */
function applySpeciesPhoto(result,requestId,scientificName){
 if(requestId!==speciesPhotoRequest)return;
 const img=document.getElementById("speciesPhotoImg");
 const placeholder=document.getElementById("speciesPhotoPlaceholder");
 const status=document.getElementById("speciesPhotoStatus");
 const source=document.getElementById("speciesPhotoSource");
 if(!result){
   img.hidden=true;placeholder.hidden=false;placeholder.textContent="No s’ha trobat cap imatge fiable.";
   status.textContent="No hi ha una fotografia disponible per a aquesta espècie.";return;
 }
 img.onload=()=>{
   if(requestId!==speciesPhotoRequest)return;
   img.hidden=false;placeholder.hidden=true;status.textContent="Imatge trobada a "+result.label+".";
   source.href=result.source;source.hidden=false;source.textContent="Veure font de la imatge ↗";
   // Assigna la fotografia a la bombolla de l'espècie seleccionada; com que és filla del node SVG,
   // es mou amb el zoom, el drag i l'animació. La geometria del clip coincideix amb el cercle.
   const node=root?.descendants().find(n=>n.data.level==="species" && n.data.name===scientificName);
   if(node && node._photoClipId){
     const group=g.selectAll("g.node").filter(n=>n===node);
     group.select("image.species-node-photo").attr("href",result.image).style("display",null);
     speciesPhotoCache.set(scientificName,{...result});
   }
 };
 img.onerror=()=>{
   if(requestId!==speciesPhotoRequest)return;
   img.hidden=true;placeholder.hidden=false;placeholder.textContent="La imatge no s’ha pogut carregar.";
   status.textContent="La font ha retornat una imatge inaccessible.";
 };
 img.src=result.image;
}
// La fotografía de la tarjeta abre la fuente enlazada, igual que el enlace inferior.
/* Interacciones de la ficha fotográfica individual. */
document.getElementById("speciesPhotoImg").addEventListener("click",()=>{
 const source=document.getElementById("speciesPhotoSource");
 if(!source.hidden && source.href && source.href!=="#") window.open(source.href,"_blank","noopener,noreferrer");
});
document.getElementById("speciesPhotoClose").addEventListener("click",closeSpeciesPhoto);

/* Actualiza el cuadro descriptivo del clado seleccionado. */
function updateCladeDescription(d){
 const panel=document.querySelector("#cladeDescription");
 const title=document.querySelector("#cladeDescriptionTitle");
 const text=document.querySelector("#cladeDescriptionText");
 const name=d&&d.depth>0?String(d.data.name||"").trim():"";
 const description=name?(CLADE_DESCRIPTIONS[name]||CLADE_DESCRIPTIONS[Object.keys(CLADE_DESCRIPTIONS).find(k=>k.toLocaleLowerCase("es")===name.toLocaleLowerCase("es"))]):"";
 if(!description){panel.classList.remove("visible");panel.setAttribute("aria-hidden","true");title.textContent="";text.textContent="";return;}
 title.textContent=name;text.textContent=description;panel.classList.add("visible");panel.setAttribute("aria-hidden","false");
}
/*
 * SELECCIÓN Y NAVEGACIÓN
 * Actualiza la ficha del taxón, el rastro jerárquico y la descripción del clado.
 * Al volver a la vista general se oculta la descripción contextual.
 */
/* Selecciona un nodo, actualiza la ficha y centra la visualización en ese grupo. */
function selectNode(d,animate){
 if(!d)return;focus=d;manualZoomFactor=1;hideTooltip();updateCladeDescription(d);
 document.querySelector("#vizTitle").textContent=d.depth===0?"Vista general":`${LEVEL_NAMES[d.data.level]||"tàxon"}: ${d.data.name}`;
 const name=d.depth===0?"Tots els registres":d.data.name;
 document.querySelector("#detailLevel").textContent=LEVEL_NAMES[d.data.level]||"Vista general";
 document.querySelector("#detailName").textContent=name;
 const metricValue=sizeMetric==="species"?d.speciesCount:d.obsValue;
 document.querySelector("#detailCount").textContent=fmt.format(metricValue)+(sizeMetric==="species"?" espècies":" observacions");
 document.querySelector("#detailObs").textContent=fmt.format(d.obsValue);
 document.querySelector("#detailSpecies").textContent=fmt.format(d.speciesCount);
 const pct=root.value?100*d.value/root.value:0;
 document.querySelector("#detailPct").textContent=pct.toLocaleString("ca-ES",{maximumFractionDigits:2})+" %";
 document.querySelector("#detailBar").style.width=Math.min(100,pct)+"%";
 document.querySelector("#detailPath").textContent=d.ancestors().reverse().map(n=>n.data.name).join(" › ");
 document.querySelector("#detailChildren").textContent=d.children?fmt.format(d.children.length):"Sense subdivisions";
 const compareButton=document.querySelector("#comparePhotosBtn");
 compareButton.hidden=!(d.children&&d.descendants().some(n=>n.data.level==="species")&&d!==root);
 compareButton.textContent="Comparar fotografies de "+(d.data.name||"les espècies");
 updateBreadcrumb();render();zoomTo(d,animate);
}
/* Actualiza la ruta de navegación para reflejar el nivel taxonómico actual. */
function updateBreadcrumb(){
 const el=document.querySelector("#breadcrumb");el.innerHTML="";
 const chain=(focus||root).ancestors().reverse();
 chain.forEach((n,i)=>{if(i)el.append(" › ");const b=document.createElement("button");b.textContent=n.depth===0?"Vista general":n.data.name;b.type="button";b.onclick=()=>selectNode(n,true);el.append(b);});
}
/* CONTROLES: navegación jerárquica, zoom y variable de tamaño */
document.querySelector("#backBtn").addEventListener("click",()=>{if(focus&&focus.parent)selectNode(focus.parent,true);});
document.querySelector("#resetBtn").addEventListener("click",()=>selectNode(root,true));
document.querySelector("#zoomInBtn").addEventListener("click",()=>{
 // El zoom es acumulativo: permite acercarse varias veces a las burbujas pequeñas.
 manualZoomFactor=Math.min(12,manualZoomFactor*1.5);
 zoomTo(focus||root,true,manualZoomFactor);
});
document.querySelector("#zoomOutBtn").addEventListener("click",()=>{
 // Alejarse un paso, sin sobrepasar el encuadre normal del grupo seleccionado.
 manualZoomFactor=Math.max(1,manualZoomFactor/1.5);
 zoomTo(focus||root,true,manualZoomFactor);
});
document.querySelector("#sizeMetric").addEventListener("change",e=>{
 sizeMetric=e.target.value;
 if(root){root=buildHierarchy(currentRows);pack=d3.pack().size([Math.max(250,width-24),Math.max(320,height-24)]).padding(4);pack(root);focus=root;renderLegend();render();selectNode(root,false);preloadAllSpeciesPhotos();}
});
/*
 * CONTROLES Y EVENTOS
 * Los botones permiten volver atrás, reiniciar la vista, ajustar el zoom y cambiar
 * la métrica. También se puede cargar un CSV alternativo si se habilita el control.
 */
/* Importación opcional de un CSV externo para reutilizar la visualización con otros datos. */
document.querySelector("#csvFile").addEventListener("change",async e=>{
 const file=e.target.files&&e.target.files[0];if(!file)return;
 try{const text=await file.text();const rows=parseCSV(text);loadRows(rows,file.name);}
 catch(err){document.querySelector("#status").textContent="No s’ha pogut carregar el CSV: "+err.message;document.querySelector("#status").classList.add("error");}
 e.target.value="";
});
/* Al cambiar el tamaño de la ventana, reconstruye el SVG con las dimensiones disponibles. */
window.addEventListener("resize",()=>{if(currentRows.length){const oldName=focus?.data?.name;initSVG();root=buildHierarchy(currentRows);pack=d3.pack().size([Math.max(250,width-24),Math.max(320,height-24)]).padding(3);root=pack(root);root.each(d=>{d.x+=12;d.y+=12;});focus=root;view=null;render();selectNode(root,false);preloadAllSpeciesPhotos();}});
/*
 * INICIO
 * Al abrir la página se decodifican los datos integrados y se construye la
 * visualización con el tamaño real disponible en la ventana.
 */
try{
 const rows=parseCSV(decodeCSV(EMBEDDED_CSV_B64));
 // Fit to actual dimensions on initial load.
 initSVG();loadRows(rows,currentFile);
}catch(err){document.querySelector("#status").textContent="Error en iniciar: "+err.message;document.querySelector("#status").classList.add("error");}
